export const sources: Record<string, string> = {
  "basic": "'use client';\n\nimport React from 'react';\nimport { Tabs } from '@ceebee/ui/client';\nimport type { TabsProps } from '@ceebee/ui/client';\n\nconst onChange = (key: string) => {\n  console.log(key);\n};\n\nconst items: TabsProps['items'] = [\n  {\n    key: '1',\n    label: 'Tab 1',\n    children: 'Content of Tab Pane 1',\n  },\n  {\n    key: '2',\n    label: 'Tab 2',\n    children: 'Content of Tab Pane 2',\n  },\n  {\n    key: '3',\n    label: 'Tab 3',\n    children: 'Content of Tab Pane 3',\n  },\n];\n\nconst App: React.FC = () => <Tabs defaultActiveKey=\"1\" items={items} onChange={onChange} />;\n\nexport default App;\n",
  "card": "'use client';\n\nimport React from 'react';\nimport { Tabs } from '@ceebee/ui/client';\n\nconst onChange = (key: string) => {\n  console.log(key);\n};\n\nconst App: React.FC = () => (\n  <Tabs\n    onChange={onChange}\n    type=\"card\"\n    items={Array.from({ length: 3 }).map((_, i) => {\n      const id = String(i + 1);\n      return {\n        label: `Tab ${id}`,\n        key: id,\n        children: `Content of Tab Pane ${id}`,\n      };\n    })}\n  />\n);\n\nexport default App;\n",
  "centered": "'use client';\n\nimport React from 'react';\nimport { Tabs } from '@ceebee/ui/client';\n\nconst App: React.FC = () => (\n  <Tabs\n    defaultActiveKey=\"1\"\n    centered\n    items={Array.from({ length: 3 }).map((_, i) => {\n      const id = String(i + 1);\n      return {\n        label: `Tab ${id}`,\n        key: id,\n        children: `Content of Tab Pane ${id}`,\n      };\n    })}\n  />\n);\n\nexport default App;\n",
  "custom-add-trigger": "'use client';\n\nimport React, { useRef, useState } from 'react';\nimport { Button, Tabs } from '@ceebee/ui/client';\n\ntype TargetKey = React.MouseEvent | React.KeyboardEvent | string;\n\nconst defaultPanes = Array.from({ length: 2 }).map((_, index) => {\n  const id = String(index + 1);\n  return { label: `Tab ${id}`, children: `Content of Tab Pane ${index + 1}`, key: id };\n});\n\nconst App: React.FC = () => {\n  const [activeKey, setActiveKey] = useState(defaultPanes[0]!.key);\n  const [items, setItems] = useState(defaultPanes);\n  const newTabIndex = useRef(0);\n\n  const onChange = (key: string) => {\n    setActiveKey(key);\n  };\n\n  const add = () => {\n    const newActiveKey = `newTab${newTabIndex.current++}`;\n    setItems([...items, { label: 'New Tab', children: 'New Tab Pane', key: newActiveKey }]);\n    setActiveKey(newActiveKey);\n  };\n\n  const remove = (targetKey: TargetKey) => {\n    const targetIndex = items.findIndex((pane) => pane.key === targetKey);\n    const newPanes = items.filter((pane) => pane.key !== targetKey);\n    if (newPanes.length && targetKey === activeKey) {\n      const { key } = newPanes[targetIndex === newPanes.length ? targetIndex - 1 : targetIndex]!;\n      setActiveKey(key);\n    }\n    setItems(newPanes);\n  };\n\n  const onEdit = (targetKey: TargetKey, action: 'add' | 'remove') => {\n    if (action === 'add') {\n      add();\n    } else {\n      remove(targetKey);\n    }\n  };\n\n  return (\n    <div>\n      <div style={{ marginBottom: 16 }}>\n        <Button onClick={add}>ADD</Button>\n      </div>\n      <Tabs\n        hideAdd\n        onChange={onChange}\n        activeKey={activeKey}\n        type=\"editable-card\"\n        onEdit={onEdit}\n        items={items}\n      />\n    </div>\n  );\n};\n\nexport default App;\n",
  "custom-indicator": "'use client';\n\nimport React from 'react';\nimport { Segmented, Tabs } from '@ceebee/ui/client';\nimport type { TabsProps } from '@ceebee/ui/client';\n\nconst onChange = (key: string) => {\n  console.log(key);\n};\n\nconst items: TabsProps['items'] = [\n  { key: '1', label: 'Tab 1', children: 'Content of Tab Pane 1' },\n  { key: '2', label: 'Tab 2', children: 'Content of Tab Pane 2' },\n  { key: '3', label: 'Tab 3', children: 'Content of Tab Pane 3' },\n];\n\ntype Align = 'start' | 'center' | 'end';\n\nconst App: React.FC = () => {\n  const [alignValue, setAlignValue] = React.useState<Align>('center');\n  return (\n    <>\n      <Segmented\n        value={alignValue}\n        style={{ marginBottom: 8 }}\n        onChange={setAlignValue}\n        options={['start', 'center', 'end']}\n      />\n      <Tabs\n        defaultActiveKey=\"1\"\n        items={items}\n        onChange={onChange}\n        indicator={{ size: (origin) => origin - 20, align: alignValue }}\n      />\n    </>\n  );\n};\n\nexport default App;\n",
  "custom-tab-bar-node": "'use client';\n\nimport React, { useState } from 'react';\nimport type { DragEndEvent } from '@dnd-kit/core';\nimport { closestCenter, DndContext, PointerSensor, useSensor } from '@dnd-kit/core';\nimport {\n  arrayMove,\n  horizontalListSortingStrategy,\n  SortableContext,\n  useSortable,\n} from '@dnd-kit/sortable';\nimport { CSS } from '@dnd-kit/utilities';\nimport { Tabs } from '@ceebee/ui/client';\nimport type { TabsProps } from '@ceebee/ui/client';\nimport { createStyles } from 'antd-style';\n\nconst useStyles = createStyles((props) => {\n  const { css, prefixCls } = props;\n  return {\n    root: css`\n      margin: 0;\n      &.${prefixCls}-tabs-editable {\n        .${prefixCls}-tabs-nav {\n          .${prefixCls}-tabs-tab {\n            /* set transition to none when type=\"editable-card\" */\n            transition: none;\n          }\n        }\n      }\n    `,\n  };\n});\n\ninterface DraggableTabPaneProps extends React.HTMLAttributes<HTMLDivElement> {\n  'data-node-key': string;\n}\n\nconst DraggableTabNode: React.FC<Readonly<DraggableTabPaneProps>> = (props) => {\n  const { className, ...rest } = props;\n\n  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({\n    id: rest['data-node-key'],\n  });\n\n  const style: React.CSSProperties = {\n    ...rest.style,\n    transform: CSS.Translate.toString(transform),\n    transition,\n    cursor: 'move',\n  };\n\n  return React.cloneElement(rest.children as React.ReactElement<any>, {\n    ref: setNodeRef,\n    style,\n    ...attributes,\n    ...listeners,\n  });\n};\n\nconst App: React.FC = () => {\n  const { styles } = useStyles();\n\n  const [items, setItems] = useState<NonNullable<TabsProps['items']>>([\n    { key: '1', label: 'Tab 1', children: 'Content of Tab Pane 1' },\n    { key: '2', label: 'Tab 2', children: 'Content of Tab Pane 2' },\n    { key: '3', label: 'Tab 3', children: 'Content of Tab Pane 3' },\n  ]);\n\n  const sensor = useSensor(PointerSensor, { activationConstraint: { distance: 10 } });\n\n  const onDragEnd = ({ active, over }: DragEndEvent) => {\n    if (active.id !== over?.id) {\n      setItems((prev) => {\n        const activeIndex = prev.findIndex((i) => i.key === active.id);\n        const overIndex = prev.findIndex((i) => i.key === over?.id);\n        return arrayMove(prev, activeIndex, overIndex);\n      });\n    }\n  };\n\n  return (\n    <Tabs\n      items={items}\n      rootClassName={styles.root}\n      renderTabBar={(tabBarProps, DefaultTabBar) => (\n        <DndContext sensors={[sensor]} onDragEnd={onDragEnd} collisionDetection={closestCenter}>\n          <SortableContext items={items.map((i) => i.key)} strategy={horizontalListSortingStrategy}>\n            <DefaultTabBar {...tabBarProps}>\n              {(node) => (\n                <DraggableTabNode\n                  {...(node as React.ReactElement<DraggableTabPaneProps>).props}\n                  key={node.key}\n                >\n                  {node}\n                </DraggableTabNode>\n              )}\n            </DefaultTabBar>\n          </SortableContext>\n        </DndContext>\n      )}\n    />\n  );\n};\n\nexport default App;\n",
  "custom-tab-bar": "'use client';\n\nimport React from 'react';\nimport type { TabsProps } from '@ceebee/ui/client';\nimport { Tabs, theme } from '@ceebee/ui/client';\nimport StickyBox from 'react-sticky-box';\n\nconst items = Array.from({ length: 3 }).map((_, i) => {\n  const id = String(i + 1);\n  return {\n    label: `Tab ${id}`,\n    key: id,\n    children: `Content of Tab Pane ${id}`,\n    style: i === 0 ? { height: 200 } : undefined,\n  };\n});\n\nconst App: React.FC = () => {\n  const {\n    token: { colorBgContainer },\n  } = theme.useToken();\n  const renderTabBar: TabsProps['renderTabBar'] = (props, DefaultTabBar) => (\n    <StickyBox offsetTop={64} offsetBottom={20} style={{ zIndex: 1 }}>\n      <DefaultTabBar {...props} style={{ background: colorBgContainer }} />\n    </StickyBox>\n  );\n  return <Tabs defaultActiveKey=\"1\" renderTabBar={renderTabBar} items={items} />;\n};\n\nexport default App;\n",
  "disabled": "'use client';\n\nimport React from 'react';\nimport { Tabs } from '@ceebee/ui/client';\n\nconst App: React.FC = () => (\n  <Tabs\n    defaultActiveKey=\"1\"\n    items={[\n      {\n        label: 'Tab 1',\n        key: '1',\n        children: 'Tab 1',\n      },\n      {\n        label: 'Tab 2',\n        key: '2',\n        children: 'Tab 2',\n        disabled: true,\n      },\n      {\n        label: 'Tab 3',\n        key: '3',\n        children: 'Tab 3',\n      },\n    ]}\n  />\n);\n\nexport default App;\n",
  "editable-card": "'use client';\n\nimport React, { useRef, useState } from 'react';\nimport { Tabs } from '@ceebee/ui/client';\n\ntype TargetKey = React.MouseEvent | React.KeyboardEvent | string;\n\nconst initialItems = [\n  { label: 'Tab 1', children: 'Content of Tab 1', key: '1' },\n  { label: 'Tab 2', children: 'Content of Tab 2', key: '2' },\n  {\n    label: 'Tab 3',\n    children: 'Content of Tab 3',\n    key: '3',\n    closable: false,\n  },\n];\n\nconst App: React.FC = () => {\n  const [activeKey, setActiveKey] = useState(initialItems[0]!.key);\n  const [items, setItems] = useState(initialItems);\n  const newTabIndex = useRef(0);\n\n  const onChange = (newActiveKey: string) => {\n    setActiveKey(newActiveKey);\n  };\n\n  const add = () => {\n    const newActiveKey = `newTab${newTabIndex.current++}`;\n    const newPanes = [...items];\n    newPanes.push({ label: 'New Tab', children: 'Content of new Tab', key: newActiveKey });\n    setItems(newPanes);\n    setActiveKey(newActiveKey);\n  };\n\n  const remove = (targetKey: TargetKey) => {\n    let newActiveKey = activeKey;\n    let lastIndex = -1;\n    items.forEach((item, i) => {\n      if (item.key === targetKey) {\n        lastIndex = i - 1;\n      }\n    });\n    const newPanes = items.filter((item) => item.key !== targetKey);\n    if (newPanes.length && newActiveKey === targetKey) {\n      if (lastIndex >= 0) {\n        newActiveKey = newPanes[lastIndex]!.key;\n      } else {\n        newActiveKey = newPanes[0]!.key;\n      }\n    }\n    setItems(newPanes);\n    setActiveKey(newActiveKey);\n  };\n\n  const onEdit = (\n    targetKey: React.MouseEvent | React.KeyboardEvent | string,\n    action: 'add' | 'remove',\n  ) => {\n    if (action === 'add') {\n      add();\n    } else {\n      remove(targetKey);\n    }\n  };\n\n  return (\n    <Tabs\n      type=\"editable-card\"\n      onChange={onChange}\n      activeKey={activeKey}\n      onEdit={onEdit}\n      items={items}\n    />\n  );\n};\n\nexport default App;\n",
  "extra": "'use client';\n\nimport React, { useMemo, useState } from 'react';\nimport { Button, Checkbox, Divider, Tabs } from '@ceebee/ui/client';\n\nconst CheckboxGroup = Checkbox.Group;\n\nconst operations = <Button>Extra Action</Button>;\n\nconst operationsSlot: Record<PositionType, React.ReactNode> = {\n  left: <Button style={{ marginInlineEnd: 16 }}>Left Extra Action</Button>,\n  right: <Button style={{ marginInlineStart: 16 }}>Right Extra Action</Button>,\n};\n\nconst options = ['left', 'right'];\n\ntype PositionType = 'left' | 'right';\n\ntype TabBarExtraMap = Partial<Record<PositionType, React.ReactNode>>;\n\nconst items = Array.from({ length: 3 }).map((_, i) => {\n  const id = String(i + 1);\n  return {\n    label: `Tab ${id}`,\n    key: id,\n    children: `Content of tab ${id}`,\n  };\n});\n\nconst App: React.FC = () => {\n  const [position, setPosition] = useState<PositionType[]>(['left', 'right']);\n\n  const slot = useMemo(() => {\n    if (position.length === 0) {\n      return null;\n    }\n    return position.reduce<TabBarExtraMap>(\n      (acc, direction) => ({ ...acc, [direction]: operationsSlot[direction] }),\n      {},\n    );\n  }, [position]);\n\n  return (\n    <>\n      <Tabs tabBarExtraContent={operations} items={items} />\n      <br />\n      <br />\n      <br />\n      <div>You can also specify its direction or both side</div>\n      <Divider />\n      <CheckboxGroup<PositionType> options={options} value={position} onChange={setPosition} />\n      <br />\n      <br />\n      <Tabs tabBarExtraContent={slot} items={items} />\n    </>\n  );\n};\n\nexport default App;\n",
  "icon": "'use client';\n\nimport React from 'react';\nimport { AndroidOutlined, AppleOutlined } from '@ant-design/icons';\nimport { Tabs } from '@ceebee/ui/client';\n\n// Icons from third-party libraries (e.g. lucide, react-icons) render as a bare `<svg>`\n// rather than an `.anticon` wrapper. It stays vertically centred with the label.\nconst HeartIcon: React.FC = () => (\n  <svg viewBox=\"0 0 24 24\" width=\"1em\" height=\"1em\" fill=\"currentColor\" aria-hidden=\"true\">\n    <path d=\"M12 20.7l-1.4-1.3C5.4 14.8 2 11.7 2 8a5 5 0 0 1 10-1.7A5 5 0 0 1 22 8c0 3.7-3.4 6.8-8.6 11.4L12 20.7z\" />\n  </svg>\n);\n\nconst App: React.FC = () => (\n  <Tabs\n    defaultActiveKey=\"2\"\n    items={[\n      { key: '1', label: 'Tab 1', children: 'Tab 1', icon: <AppleOutlined /> },\n      { key: '2', label: 'Tab 2', children: 'Tab 2', icon: <AndroidOutlined /> },\n      { key: '3', label: 'Tab 3', children: 'Tab 3', icon: <HeartIcon /> },\n    ]}\n  />\n);\n\nexport default App;\n",
  "placement": "'use client';\n\nimport React, { useState } from 'react';\nimport type { RadioChangeEvent, TabsProps } from '@ceebee/ui/client';\nimport { Radio, Space, Tabs } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [tabPlacement, setTabPlacement] = useState<TabsProps['tabPlacement']>('start');\n\n  const changeTabPlacement = (e: RadioChangeEvent) => {\n    setTabPlacement(e.target.value);\n  };\n\n  return (\n    <>\n      <Space style={{ marginBottom: 24 }}>\n        Tab placement:\n        <Radio.Group value={tabPlacement} onChange={changeTabPlacement}>\n          <Radio.Button value=\"top\">top</Radio.Button>\n          <Radio.Button value=\"bottom\">bottom</Radio.Button>\n          <Radio.Button value=\"start\">start</Radio.Button>\n          <Radio.Button value=\"end\">end</Radio.Button>\n        </Radio.Group>\n      </Space>\n      <Tabs\n        tabPlacement={tabPlacement}\n        items={Array.from({ length: 3 }).map((_, i) => {\n          const id = String(i + 1);\n          return {\n            label: `Tab ${id}`,\n            key: id,\n            children: `Content of Tab ${id}`,\n          };\n        })}\n      />\n    </>\n  );\n};\n\nexport default App;\n",
  "popupRender-Search": "'use client';\n\nimport React, { useMemo, useRef, useState } from 'react';\nimport { Input, Menu, Tabs } from '@ceebee/ui/client';\nimport { SearchOutlined } from '@ant-design/icons';\nimport { createStyles } from 'antd-style';\nimport type { TabsProps } from '@ceebee/ui/client';\n\nconst useSearchPopupStyle = createStyles(({ token, css }) => ({\n  container: css`\n    width: 200px;\n    background: ${token.colorBgContainer};\n    box-shadow: ${token.boxShadow};\n    border-radius: ${token.borderRadiusLG}px;\n    overflow: hidden;\n  `,\n  searchWrapper: css`\n    padding: ${token.paddingXS}px ${token.paddingSM}px;\n    border-bottom: ${token.lineWidth}px ${token.lineType} ${token.colorBorder};\n  `,\n  menuWrapper: css`\n    max-height: 300px;\n    overflow-y: auto;\n  `,\n  empty: css`\n    padding: ${token.paddingSM}px;\n    color: ${token.colorTextDisabled};\n    text-align: center;\n  `,\n}));\n\nconst items: TabsProps['items'] = Array.from({ length: 30 }, (_, i) => {\n  const id = String(i);\n  return {\n    label: `Tab-${id}`,\n    key: id,\n    disabled: i === 28,\n    children: `Content of tab ${id}`,\n  };\n});\n\nconst SearchPopup = ({\n  restTabs,\n  activeKey,\n  onChange,\n}: {\n  restTabs: any[];\n  activeKey: string;\n  onChange: (key: string) => void;\n}) => {\n  const [searchTerm, setSearchTerm] = useState('');\n  const menuRef = useRef<any>(null);\n  const { styles } = useSearchPopupStyle();\n\n  const fullTabs = useMemo(\n    () => restTabs.map((item) => ({ key: item.key, label: item.label, disabled: item.disabled })),\n    [restTabs],\n  );\n\n  const filterTabs = useMemo(\n    () =>\n      !searchTerm\n        ? fullTabs\n        : fullTabs.filter((tab) =>\n            String(tab.label).toLowerCase().includes(searchTerm.toLowerCase()),\n          ),\n    [fullTabs, searchTerm],\n  );\n\n  return (\n    <div className={styles.container}>\n      <div className={styles.searchWrapper}>\n        <Input\n          placeholder=\"Search tabs...\"\n          prefix={<SearchOutlined />}\n          value={searchTerm}\n          onChange={(e) => setSearchTerm(e.target.value)}\n          onKeyDown={(e) => {\n            if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {\n              menuRef.current?.focus();\n            }\n          }}\n          allowClear\n        />\n      </div>\n      <div className={styles.menuWrapper}>\n        <Menu\n          ref={menuRef}\n          defaultSelectedKeys={[activeKey]}\n          items={filterTabs}\n          onClick={({ key }) => {\n            setSearchTerm('');\n            onChange(key);\n          }}\n        />\n      </div>\n      {filterTabs.length === 0 && <div className={styles.empty}>No matching tabs</div>}\n    </div>\n  );\n};\n\nconst App: React.FC = () => {\n  const [activeKey, setActiveKey] = React.useState('1');\n\n  return (\n    <Tabs\n      activeKey={activeKey}\n      onChange={setActiveKey}\n      items={items}\n      more={{\n        trigger: 'click',\n        placement: 'bottomLeft',\n        popupRender: (_, { restTabs, onClose }) => (\n          <SearchPopup\n            restTabs={restTabs}\n            activeKey={activeKey}\n            onChange={(key) => {\n              setActiveKey(key);\n              onClose();\n            }}\n          />\n        ),\n      }}\n    />\n  );\n};\n\nexport default App;\n",
  "size": "'use client';\n\nimport React, { useRef, useState } from 'react';\nimport type { RadioChangeEvent, TabsProps } from '@ceebee/ui/client';\nimport { Radio, Tabs } from '@ceebee/ui/client';\n\ntype TargetKey = React.MouseEvent | React.KeyboardEvent | string;\n\nconst App: React.FC = () => {\n  const [size, setSize] = useState<'small' | 'medium' | 'large'>('small');\n  const [activeKey, setActiveKey] = useState('1');\n  const [items, setItems] = useState<TabsProps['items']>([\n    {\n      label: 'Tab 1',\n      key: '1',\n      children: 'Content of editable tab 1',\n    },\n    {\n      label: 'Tab 2',\n      key: '2',\n      children: 'Content of editable tab 2',\n    },\n    {\n      label: 'Tab 3',\n      key: '3',\n      children: 'Content of editable tab 3',\n    },\n  ]);\n  const newTabIndex = useRef(0);\n\n  const add = () => {\n    const newActiveKey = `newTab${newTabIndex.current++}`;\n    setItems([\n      ...(items || []),\n      {\n        label: 'New Tab',\n        key: newActiveKey,\n        children: 'Content of new Tab',\n      },\n    ]);\n    setActiveKey(newActiveKey);\n  };\n\n  const remove = (targetKey: TargetKey) => {\n    if (!items) {\n      return;\n    }\n    const targetIndex = items.findIndex((item) => item.key === targetKey);\n    const newItems = items.filter((item) => item.key !== targetKey);\n\n    if (newItems.length && targetKey === activeKey) {\n      const newActiveKey =\n        newItems[targetIndex === newItems.length ? targetIndex - 1 : targetIndex]!.key;\n      setActiveKey(newActiveKey);\n    }\n\n    setItems(newItems);\n  };\n\n  const onEdit = (targetKey: TargetKey, action: 'add' | 'remove') => {\n    if (action === 'add') {\n      add();\n    } else {\n      remove(targetKey);\n    }\n  };\n\n  const onChange = (e: RadioChangeEvent) => {\n    setSize(e.target.value);\n  };\n\n  return (\n    <div>\n      <Radio.Group value={size} onChange={onChange} style={{ marginBottom: 16 }}>\n        <Radio.Button value=\"small\">Small</Radio.Button>\n        <Radio.Button value=\"medium\">Medium</Radio.Button>\n        <Radio.Button value=\"large\">Large</Radio.Button>\n      </Radio.Group>\n      <Tabs\n        defaultActiveKey=\"1\"\n        size={size}\n        style={{ marginBottom: 32 }}\n        items={Array.from({ length: 3 }).map((_, i) => {\n          const id = String(i + 1);\n          return {\n            label: `Tab ${id}`,\n            key: id,\n            children: `Content of tab ${id}`,\n          };\n        })}\n      />\n      <Tabs\n        defaultActiveKey=\"1\"\n        type=\"card\"\n        size={size}\n        style={{ marginBottom: 32 }}\n        items={Array.from({ length: 3 }).map((_, i) => {\n          const id = String(i + 1);\n          return {\n            label: `Card Tab ${id}`,\n            key: id,\n            children: `Content of card tab ${id}`,\n          };\n        })}\n      />\n      <Tabs\n        type=\"editable-card\"\n        size={size}\n        activeKey={activeKey}\n        onChange={setActiveKey}\n        onEdit={onEdit}\n        items={items}\n      />\n    </div>\n  );\n};\n\nexport default App;\n",
  "slide": "'use client';\n\nimport React, { useState } from 'react';\nimport type { RadioChangeEvent, TabsProps } from '@ceebee/ui/client';\nimport { Radio, Tabs } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [mode, setMode] = useState<TabsProps['tabPlacement']>('top');\n\n  const handleModeChange = (e: RadioChangeEvent) => {\n    setMode(e.target.value);\n  };\n\n  return (\n    <div>\n      <Radio.Group onChange={handleModeChange} value={mode} style={{ marginBottom: 8 }}>\n        <Radio.Button value=\"top\">Horizontal</Radio.Button>\n        <Radio.Button value=\"left\">Vertical</Radio.Button>\n      </Radio.Group>\n      <Tabs\n        defaultActiveKey=\"1\"\n        tabPlacement={mode}\n        style={{ height: 220 }}\n        items={Array.from({ length: 30 }, (_, i) => {\n          const id = String(i);\n          return {\n            label: `Tab-${id}`,\n            key: id,\n            disabled: i === 28,\n            children: `Content of tab ${id}`,\n          };\n        })}\n      />\n    </div>\n  );\n};\n\nexport default App;\n",
  "style-class": "'use client';\n\nimport React from 'react';\nimport { Flex, Tabs } from '@ceebee/ui/client';\nimport type { GetProp, TabsProps } from '@ceebee/ui/client';\nimport { createStaticStyles } from 'antd-style';\n\nconst classNames = createStaticStyles(({ css }) => ({\n  root: css`\n    border-width: 2px;\n    border-style: dashed;\n    padding: 16px;\n    margin-bottom: 10px;\n  `,\n}));\n\nconst stylesObject: TabsProps['styles'] = {\n  root: { borderWidth: 2, borderStyle: 'dashed', padding: 16, marginBottom: 10 },\n  header: { backgroundColor: 'rgba(245,245,245,0.5)' },\n  item: { fontWeight: 'bold', color: '#1890ff', padding: `6px 10px` },\n  indicator: { backgroundColor: 'rgba(255,77,79, 0.3)', height: 4 },\n  body: { backgroundColor: 'rgba(230,247,255,0.8)' },\n  content: { padding: 16 },\n};\n\nconst stylesFn: TabsProps['styles'] = (info): GetProp<TabsProps, 'styles', 'Return'> => {\n  if (info.props.type === 'card') {\n    return {\n      root: { backgroundColor: 'rgba(250,250,250, 0.8)', borderColor: '#d9d9d9' },\n      header: { textAlign: 'start' },\n    };\n  }\n  return {};\n};\n\nconst items = [\n  {\n    key: '1',\n    label: 'Tab 1',\n    children: 'Content of Tab Pane 1',\n  },\n  {\n    key: '2',\n    label: 'Tab 2',\n    children: 'Content of Tab Pane 2',\n  },\n  {\n    key: '3',\n    label: 'Tab 3',\n    children: 'Content of Tab Pane 3',\n  },\n];\n\nconst App: React.FC = () => {\n  const shareProps: TabsProps = {\n    items,\n    defaultActiveKey: '1',\n    classNames,\n  };\n\n  return (\n    <Flex vertical gap=\"medium\">\n      <Tabs {...shareProps} styles={stylesObject} />\n      <Tabs tabPlacement=\"start\" type=\"card\" {...shareProps} styles={stylesFn} />\n    </Flex>\n  );\n};\n\nexport default App;\n"
};
